const TOTAL_LESSONS = 10;
let completed = 2;

// Function 1: getStatus - pure, returns string
const getStatus = (lessonId, completed) => {
 if (lessonId <= completed) return "completed";
 if (lessonId === completed + 1) return "current";
 return "locked";
};

// Function 2: calculateProgress - pure, returns object
function calculateProgress(completed, total = TOTAL_LESSONS) {
 completed = Math.min(total, Math.max(0, Number(completed) || 0));
 let percent = Math.round((completed / total) * 100);
 return { completed, total, percent, text: `${completed} / ${total} completed` };
}

// Function 3: createCard - returns card object with secure data handling
function createCard(lesson, completed) {
 let status = getStatus(lesson.id, completed);
 let isLocked = status === 'locked';
 let badge = status === 'completed'? 'Completed' : status === 'current'? 'Current' : 'Locked';
 let button = isLocked? 'Locked' : status === 'completed'? 'Review' : 'Start Lesson';

 return {
 id: lesson.id,
 title: lesson.title, // In real DOM would be textContent safe
 status,
 badge,
 button,
 xp: lesson.xp,
 locked: isLocked,
 // Callback for click - closure over id and status
 onClick: () => {
 if (isLocked) {
 console.log(`🔒 Lesson ${lesson.id} locked - need ${completed + 1} first`);
 return false;
 }
 console.log(`→ Navigate to lesson.html?lesson=${lesson.id}`);
 return true;
 }
 };
}

