console.log(`Lesson 1 with completed 2: ${getStatus(1, 2)}`); // completed
console.log(`Lesson 3 with completed 2: ${getStatus(3, 2)}`); // current
console.log(`Lesson 5 with completed 2: ${getStatus(5, 2)}`); // locked

console.log('\ncalculateProgress tests:');
console.log(calculateProgress(2, 10)); // {completed:2, total:10, percent:20, text:2/10 completed}
console.log(calculateProgress(5)); // 50% with default total 10

