const TOTAL_LESSONS = 10;
const COURSE_ID = "javascript";

let lessons = [
 {id: 1, title: 'Introduction to JavaScript', learn: 'Understand JS', summary: 'Learn syntax', xp: 100},
 {id: 2, title: 'Variables', learn: 'Store info', summary: 'Learn let, const', xp: 100},
 {id: 3, title: 'Operators', learn: 'Math and logic', summary: 'Master operators', xp: 100},
 {id: 4, title: 'Conditions', learn: 'Decisions', summary: 'Learn if/else', xp: 100},
 {id: 5, title: 'Loops', learn: 'Repetition', summary: 'Learn for, while', xp: 100}
];

let user = { xp: 200, coins: 20, completed: 2, progress: { javascript: 2 }, profile: { name: "Prince" } };

// All functions from lessons 1-9 combined
const getStatus = (id, completed) => id <= completed? 'completed' : id === completed + 1? 'current' : 'locked';
const calculateProgress = (completed, total = TOTAL_LESSONS) => {
 let safe = Math.min(total, Math.max(0, Number(completed) || 0));
 return { completed: safe, total, percent: Math.round((safe / total) * 100), text: `${safe} / ${total} completed` };
};

function createCard(lesson, completed) {
 let status = getStatus(lesson.id, completed);
 let badge = status === 'completed'? 'Completed' : status === 'current'? 'Current' : 'Locked';
 let button = status === 'locked'? 'Locked' : status === 'completed'? 'Review' : 'Start Lesson';
 return { id: lesson.id, title: lesson.title, status, badge, button, xp: lesson.xp, dataset: { lesson: lesson.id } };
}

function renderEfficient(lessons, completed) {
 let grid = { children: [] };
 lessons.forEach(lesson => {
 let card = createCard(lesson, completed);
 let icon = card.status === 'completed'? '✅' : card.status === 'current'? '▶' : '🔒';
 console.log(`${icon} ${card.id}. ${card.title} - ${card.status.toUpperCase()} - [${card.button}] - ${card.xp} XP`);
 grid.children.push(card);
 });
 console.log(`Rendered ${grid.children.length} cards - 1 reflow efficient`);
 return grid;
}

