 grid.addEventListener = (e, cb) => { grid.cb = cb; };
 grid.addEventListener('click', (event) => {
 let id = event.target?.dataset?.lesson;
 if (id) {
 let numId = Number(id);
 let status = getStatus(numId, user.completed);
 if (status === 'locked') {
 console.log(`🔒 Lesson ${numId} locked`);
