 // Complete
 let newLessons = lessons.map(l => {
 if (l.id === numId) return {...l, xp: 100};
 return l;
 });
 let newUser = {...user, xp: user.xp + 100, completed: user.completed + 1};
 user = newUser;
 lessons = newLessons;
 let prog = calculateProgress(user.completed);
 console.log(`🎉 Completed! XP: ${user.xp}, ${prog.text} - ${prog.percent}%`);
 renderEfficient(lessons, user.completed);
 }
 }
 }
 });
