// 1. Data - you create
const TOTAL = 10;
let myLessons = [
 {id: 1, title: 'Intro', xp: 100},
 {id: 2, title: 'Variables', xp: 100},
 {id: 3, title: 'Operators', xp: 100}
];
let myUser = { xp: 0, completed: 0 };

// 2. Functions - you build
const myGetStatus = (id, completed) => {
 // Your code: id <= completed? completed : id === completed+1? current : locked
 if (id <= completed) return "completed";
 if (id === completed + 1) return "current";
 return "locked";
};

function myCalculateProgress(completed, total = TOTAL) {
 // Your code: Math.min, Math.max, Math.round, template literal
 completed = Math.min(total, Math.max(0, Number(completed) || 0));
 let percent = Math.round((completed / total) * 100);
 return { completed, total, percent, text: `${completed} / ${total} completed` };
}

function myCreateCard(lesson, completed) {
 // Your code: getStatus, badge, button, return card
 let status = myGetStatus(lesson.id, completed);
 return { id: lesson.id, title: lesson.title, status, button: status === 'locked'? 'Locked' : 'Start' };
}

// 3. Render - you build efficient
function myRender(lessons, completed) {
 // Your code: grid in memory, forEach, append once 1 reflow
 let grid = [];
 lessons.forEach(l => {
 let card = myCreateCard(l, completed);
 grid.push(card);
 console.log(`${card.id}. ${card.title} - ${card.status}`);
 });
 return grid;
}

// 4. Complete - you build with spread immutable
function myCompleteLesson(id) {
 // Your code: check locked, map with spread, update user with spread
 let status = myGetStatus(id, myUser.completed);
 if (status === 'locked') {
 console.log(`Locked! Need ${myUser.completed + 1}`);
 return;
 }
 let newLessons = myLessons.map(l => l.id === id? {...l, xp: 100} : l);
 let newUser = {...myUser, xp: myUser.xp + 100, completed: myUser.completed + 1};
 myLessons = newLessons;
 myUser = newUser;
 console.log(`Completed! XP: ${myUser.xp}, Completed: ${myUser.completed}`);
}

// Test your build
console.log('=== My Build ===');
myRender(myLessons, myUser.completed);
console.log(`Progress: ${myCalculateProgress(myUser.completed).text}`);
myCompleteLesson(1);
myRender(myLessons, myUser.completed);
